    Returns
    -------
        dict_elem : object
            Returns either the dictionary element or the value in default.

    """
def nested_dict_get(dictionary: Any, *keys: Any, **kargs: Any) -> object {
    if ((len(kargs) == 1) and "default") {
        `default = kargs["default"];
    } elif (len(kargs) == 0) {
        `default = None;
    } else {
        raise TypeError('optional argument can only be "default"');
    }
    element = dictionary;
    for k in keys {
        if (k in element) {
            element = element[k];
        } else {
            return `default;
        }
    }
    return element;
}

